def main():
    path = BASE/'revised-body-v2.md'
    body = path.read_text(encoding='utf-8')
    for before, after in changes:
        count = body.count(before)
        if count != 1:
            raise ValueError(f'Expected one occurrence, found {count}: {before[:110]}')
        body = body.replace(before, after, 1)
    path.write_text(body, encoding='utf-8')
    print(f'Applied {len(changes)} targeted prose repairs to the editable body.')

if __name__ == '__main__':
    main()
